import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "../../lib/cn";
import "../../styles/empty.css";

export interface EmptyProps extends Omit<ComponentPropsWithoutRef<"div">, "title"> {
  /** Optional icon or illustration shown above the title. */
  icon?: ReactNode;
  title: ReactNode;
  description?: ReactNode;
  /** Usually a Button that fixes the empty state, such as "Create project". */
  action?: ReactNode;
}

/** Placeholder for a view with no content yet. Give it one clear next step. */
export function Empty({ icon, title, description, action, className, ...props }: EmptyProps) {
  return (
    <div className={cn("eui-empty", className)} {...props}>
      {icon ? <div className="eui-empty__icon">{icon}</div> : null}
      <p className="eui-empty__title">{title}</p>
      {description ? <p className="eui-empty__description">{description}</p> : null}
      {action ? <div className="eui-empty__action">{action}</div> : null}
    </div>
  );
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Empty state. Centered, quiet, and dashed so it reads as a placeholder. */

.eui-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 32px 24px;
  text-align: center;
  border-radius: var(--eui-radius-lg);
  box-shadow: inset 0 0 0 var(--eui-border-width) var(--eui-color-border);
  background-color: var(--eui-color-surface);
}

.eui-empty__icon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  margin-bottom: 4px;
  border-radius: var(--eui-radius-base);
  color: var(--eui-color-fg-muted);
  background-color: var(--eui-color-bg);
  box-shadow: inset 0 0 0 var(--eui-border-width) var(--eui-color-border);
}

.eui-empty__title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--eui-color-fg);
}

.eui-empty__description {
  margin: 0;
  max-width: 36ch;
  font-size: 14px;
  line-height: 20px;
  color: var(--eui-color-fg-muted);
}

.eui-empty__action {
  margin-top: 8px;
}
